// Victim is logged into banking.com with session cookie
// Attacker hosts this page on evil.com:

<!DOCTYPE html>
<html>
<body onload="document.getElementById('attack').submit()">
  <form id="attack" action="https://banking.com/transfer" method="POST">
    <input type="hidden" name="toAccount" value="attacker123" />
    <input type="hidden" name="amount" value="5000" />
  </form>
</body>
</html>

// Spring Boot endpoint (vulnerable without CSRF protection):
@RestController
public class TransferController {
    @PostMapping("/transfer")
    public ResponseEntity<String> transfer(
        @RequestParam String toAccount,
        @RequestParam int amount,
        @AuthenticationPrincipal User user) {  // user extracted from session cookie

        transferService.executeTransfer(user.getId(), toAccount, amount);
        return ResponseEntity.ok("Transfer completed");  // attacker never sees this response
    }
}

// Spring Security auto-generates and validates CSRF tokens
// Enable CSRF (default in Spring Boot 3.2):
@Configuration
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.csrf(csrf -> csrf
            .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse()));
        return http.build();
    }
}

// In your Thymeleaf template, Spring auto-injects the token:
<form method="POST" action="/transfer">
    <input type="hidden" name="_csrf" value="${_csrf.token}" />  <!-- auto-populated -->
    <input type="text" name="toAccount" />
    <input type="number" name="amount" />
    <button type="submit">Transfer</button>
</form>

// For REST API with JavaScript client:
@RestController
public class CsrfController {
    @GetMapping("/csrf-token")
    public CsrfToken getCsrfToken(CsrfToken token) {
        return token;  // Spring provides the token to client
    }
}

// JavaScript client includes token in request header:
fetch('/transfer', {
    method: 'POST',
    headers: { 'X-CSRF-TOKEN': csrfToken },  // token from /csrf-token endpoint
    body: JSON.stringify({ toAccount: 'user123', amount: 100 })
});

// Spring Boot REST API with JWT authentication (stateless)
@RestController
@RequestMapping("/api")
public class OrderController {

    @PostMapping("/orders")
    public ResponseEntity<Order> createOrder(
        @RequestHeader("Authorization") String authHeader,  // JWT must be explicitly sent
        @RequestBody OrderRequest request) {

        var token = authHeader.replace("Bearer ", "");
        var userId = jwtService.extractUserId(token);  // validate and extract user
        var order = orderService.createOrder(userId, request);
        return ResponseEntity.ok(order);
    }
}

// Client JavaScript explicitly adds JWT to header:
var jwt = localStorage.getItem('authToken');  // attacker can't read this cross-origin

fetch('https://api.example.com/api/orders', {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + jwt  // not automatic — requires explicit code
    },
    body: JSON.stringify({ productId: 123, quantity: 2 })
});

// Attacker on evil.com can't access victim's localStorage
// Can't read JWT, can't add Authorization header, request fails authentication

// CSRF protection disabled for stateless API:
@Configuration
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.csrf(csrf -> csrf.disable());  // safe because no cookies used
        return http.build();
    }
}

// Configure session cookie with SameSite in Spring Boot 3.2
@Configuration
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.sessionManagement(session -> session
            .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED));
        return http.build();
    }

    @Bean
    public CookieSameSiteSupplier applicationCookieSameSiteSupplier() {
        return CookieSameSiteSupplier.ofLax();  // Lax for general web apps
    }
}

// Or set in application.yml:
server:
  servlet:
    session:
      cookie:
        same-site: lax
        secure: true
        http-only: true

// For custom cookies:
@GetMapping("/set-preference")
public ResponseEntity<String> setPreference(HttpServletResponse response) {
    var cookie = new ResponseCookie.from("user-pref", "dark-mode")
        .sameSite("Strict")  // more restrictive for non-session cookies
        .secure(true)
        .httpOnly(true)
        .maxAge(Duration.ofDays(30))
        .path("/")
        .build();

    response.addHeader("Set-Cookie", cookie.toString());
    return ResponseEntity.ok("Preference saved");
}
